$(document).ready(function() {
    // Inicializa o contador de unidades finais
    let remainingUnits = parseInt($('#remaining-units').text());

    if (!isNaN(remainingUnits)) {
        setInterval(() => {
            remainingUnits--;
            if (remainingUnits < 0) {
                remainingUnits = 2; // Reinicia o contador
            }
            $('#remaining-units').text(remainingUnits);
        }, 1000); // Atualização a cada segundo
    } else {
        console.error('Unidades inválidas');
    }
